const float PI = 3.14159265358979323846;

// -----------------------------------------------------------------------------
// Schlick Fresnel.
//
// F0 is normal-incidence reflectance.
// VdotH controls the angle at the microscopic reflecting interface.
// -----------------------------------------------------------------------------
vec3 FresnelSchlick(
    float VdotH,
    vec3 F0)
{
    float oneMinus =
        1.0 - clamp(VdotH, 0.0, 1.0);

    float oneMinus2 =
        oneMinus * oneMinus;

    float oneMinus5 =
        oneMinus2 *
        oneMinus2 *
        oneMinus;

    return
        F0 +
        (vec3(1.0) - F0) *
        oneMinus5;
}

// -----------------------------------------------------------------------------
// GGX / Trowbridge-Reitz normal distribution.
//
// perceptualRoughness is the artist/glTF parameter.
// alpha = roughness^2 is the microfacet slope parameter.
// -----------------------------------------------------------------------------
float DistributionGGX(
    float NdotH,
    float perceptualRoughness)
{
    float alpha =
        perceptualRoughness *
        perceptualRoughness;

    float alpha2 =
        alpha * alpha;

    float denominator =
        NdotH * NdotH *
        (alpha2 - 1.0) +
        1.0;

    return
        alpha2 /
        max(
            PI *
            denominator *
            denominator,
            1e-7);
}

// -----------------------------------------------------------------------------
// One-direction Schlick approximation to Smith GGX masking.
// -----------------------------------------------------------------------------
float GeometrySchlickGGX(
    float NdotX,
    float perceptualRoughness)
{
    float r =
        perceptualRoughness +
        1.0;

    // Direct-light remapping.
    float k =
        (r * r) /
        8.0;

    return
        NdotX /
        max(
            NdotX *
            (1.0 - k) +
            k,
            1e-7);
}

// -----------------------------------------------------------------------------
// Joint light/view visibility.
// -----------------------------------------------------------------------------
float GeometrySmith(
    float NdotL,
    float NdotV,
    float perceptualRoughness)
{
    return
        GeometrySchlickGGX(
            NdotL,
            perceptualRoughness)
        *
        GeometrySchlickGGX(
            NdotV,
            perceptualRoughness);
}

struct MaterialSample
{
    vec3 baseColor;
    float metallic;
    float roughness;
    float ao;
    vec3 emissive;
};

struct BRDFResult
{
    vec3 diffuse;
    vec3 specular;
    vec3 fresnel;
};

BRDFResult EvaluateBRDF(
    vec3 N,
    vec3 V,
    vec3 L,
    MaterialSample material)
{
    BRDFResult result;

    result.diffuse  = vec3(0.0);
    result.specular = vec3(0.0);
    result.fresnel  = vec3(0.0);

    float NdotL =
        max(dot(N, L), 0.0);

    float NdotV =
        max(dot(N, V), 0.0);

    if (NdotL <= 0.0 ||
        NdotV <= 0.0)
    {
        return result;
    }

    vec3 H =
        normalize(L + V);

    float NdotH =
        max(dot(N, H), 0.0);

    float VdotH =
        max(dot(V, H), 0.0);

    // Metallic workflow:
    //
    // dielectric:
    //     neutral 4% interface reflectance
    //
    // conductor:
    //     colored F0 from base color
    vec3 F0 =
        mix(
            vec3(0.04),
            material.baseColor,
            material.metallic);

    vec3 F =
        FresnelSchlick(
            VdotH,
            F0);

    float D =
        DistributionGGX(
            NdotH,
            material.roughness);

    float G =
        GeometrySmith(
            NdotL,
            NdotV,
            material.roughness);

    vec3 specular =
        D * G * F /
        max(
            4.0 *
            NdotL *
            NdotV,
            1e-6);

    // Energy reaching diffuse body scattering:
    //
    // 1-F:
    // energy not immediately reflected at interface.
    //
    // 1-metallic:
    // conductors have no ordinary diffuse body lobe.
    vec3 kD =
        (vec3(1.0) - F) *
        (1.0 - material.metallic);

    vec3 diffuse =
        kD *
        material.baseColor /
        PI;

    result.diffuse =
        diffuse;

    result.specular =
        specular;

    result.fresnel =
        F;

    return result;
}

vec3 EvaluateDirectLight(
    vec3 N,
    vec3 V,
    vec3 L,
    vec3 incidentRadiance,
    float visibility,
    MaterialSample material)
{
    float NdotL =
        max(dot(N, L), 0.0);

    if (NdotL <= 0.0)
        return vec3(0.0);

    BRDFResult brdf =
        EvaluateBRDF(
            N,
            V,
            L,
            material);

    // Rendering equation:
    //
    // Lo = f(L,V) Li (N dot L)
    return
        (
            brdf.diffuse +
            brdf.specular
        )
        *
        incidentRadiance
        *
        NdotL
        *
        visibility;
}

